#include <stdio.h>
#include <stdlib.h>

int is_prime(unsigned long n) {
    if (n <= 1) return 0;
    if (n == 2) return 1;
    if (n % 2 == 0) return 0;
    for (unsigned long i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return 0;
    }
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 1;
    }
    char *endptr;
    unsigned long num = strtoll(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("BAD_INPUT\n");
        return 1;
    }
    if (num > 4294967295) {
        printf("OUT_OF_RANGE\n");
        return 1;
    }
    if (is_prime(num)) {
        printf("PRIME\n");
    } else {
        printf("NOT_PRIME\n");
    }
    return 0;
}
